\label{thm:unique_currents}
Let $d\geq 3$ and $\beta>\beta_c$. Then,  \begin{equation}\label{eq:unique_currents}
        \lim_{L\to\infty} \inf_{A,B\subset \partial\Lambda_{10L}} \mathbf{P}^{A,B}_{\Lambda_{10L}[\beta], \Lambda_{10L}[\beta]} [U(L)] = 1,
    \end{equation}
    where the infimum is taken over all subsets of even cardinality.

\label{rem:2D local uniqueness}
    It is folklore that \eqref{eq:unique_currents} also holds for $d=2$. In fact, a stronger result, involving only the single current measure $\mathbf P^A_{\Lambda_{10L}[\beta]}$ (with $A\subset \partial \Lambda_{10L}$ of even cardinality), holds.  
    We only sketch the argument here in the simpler case $A=\emptyset$, which follows an observation of \cite{hansen2023uniform}. By planarity, local uniqueness follows from the existence of a circuit that surrounds a dyadic annulus with probability tending to $1$. Since the single sourceless random current measure stochastically dominates the high-temperature expansion (see e.g.~\cite{AizenmanDuminilTassionWarzelEmergentPlanarity2019}), it suffices to prove the existence of a circuit for the latter. The high-temperature expansion at parameter $\beta$ is distributed as the interfaces separating the sign clusters of a wired Ising model on the dual lattice at parameter $\beta^*$. By the Kramers--Wannier duality, if $\beta>\beta_c$, then $\beta^*<\beta_c$. For the subcritical Ising model, the probability of a sign-cluster crossing the annulus decays exponentially, uniformly over the boundary conditions \cite{Higuchi93}. When such a crossing does not happen, we get the desired existence of a circuit. The general case, with source set $A$ arbitrary on the boundary, follows by similar considerations\footnote{Adding sources to the single random current measure induces spin boundary conditions when passing to the dual Ising model: letting $A=\{a_1,\ldots,a_{2k}\}$ be the sources listed in cyclic order, they induce alternating sign boundary conditions on the arcs connecting $a_i$ to $a_{i+1}$. Because the exponential decay of a sign-cluster crossing is uniform in the boundary conditions, this does not affect the previous argument.}.

\label{coro: truncated} 
For every $d\geq 3$ and $\beta>\beta_c$, there exists $c=c(d,\beta)>0$ such that the following holds. For every $n\geq1$ and every finite subsets $A\subset \Lambda_n$ and $B\subset \mathbb Z^d\setminus\Lambda_{2n}$ 
    \begin{equation}\label{eq:truncated}
        \langle \sigma_A ; \sigma_B \rangle_\beta^+ \leq 
        e^{-cn} \langle \sigma_A\rangle_{\beta}^+\langle \sigma_B\rangle_{\beta}^+.
    \end{equation}
In particular, 
for every $x\in\mathbb Z^d$,
    \begin{equation}\label{eq:truncated_pt_to_pt}
        \langle \sigma_0 ; \sigma_x \rangle_\beta^+ \leq 
        e^{-c|x|}.
    \end{equation}

\label{cor: ising mixing}
	Let $d\geq 3$ and $\beta>\beta_c$. There exists $c=c(d,\beta)>0$ such that, for every $n\geq1$ and all events $E$ and $F$ depending on $\Lambda_n$ and $\mathbb Z^d\setminus \Lambda_{2n}$, respectively, 
	\begin{equation*}
		\Big| \nu^+_{\beta}[E\cap F]-\nu^+_{\beta}[E]\nu^+_{\beta}[F] \Big| \leq e^{-cn}.
	\end{equation*}

\label{cor: perco ratio mixing} 
Let $d\geq 3$ and $\beta>\beta_c$. There exists $c=c(d,\beta)>0$ such that the following properties hold. For every $n\geq 1$ and every events $E$ and $F$ depending on edges in $\Lambda_n$ and $\mathbb Z^d\setminus \Lambda_{2n}$, respectively,
	\begin{equation}\label{eq:ratio-mixing-currents}
		\Big| \mathbf{P}_{\beta}[E\cap F]-\mathbf{P}_{\beta}[E]\mathbf{P}[F] \Big| \leq e^{-cn}\mathbf{P}_{\beta}[E]\mathbf{P}_{\beta}[F],
	\end{equation}
    and
    	\begin{equation}\label{eq:ratio-mixing-FK}
		\Big| \phi_{\beta}[E\cap F]-\phi_{\beta}[E]\phi_{\beta}[F] \Big| \leq e^{-cn}\phi_{\beta}[E]\phi_{\beta}[F].
	\end{equation}

\label{prop: Griffiths} Let $G=(V,E,J)$ be a weighted graph and $\#$ be either free or plus boundary conditions. For every finite $A,B\subset V$, one has
\begin{equation*}
	\langle \sigma_A\rangle_{G}^\#\geq 0, \qquad \langle \sigma_A;\sigma_B\rangle_{G}^\#
\geq 0.
\end{equation*}

\label{prop:consequencegriffiths} Let $G=(V,E,J)$ and $H=(V',E',J')$ be two weighted graphs such that $G\subset H$ (in the sense that $V\subset V', E\subset E'$, and $J\leq J'$). For every finite $A\subset V$, one has
\begin{equation}\label{eq:monot Griffiths}
	\langle \sigma_A\rangle_{G}\leq \langle \sigma_A\rangle_{H}.
\end{equation}

\label{prop:FKG}
Let $G=(V,E,J)$ be a weighted graph and $\#$ be either free or plus boundary conditions. Let $f,g:\{-1,1\}^V\rightarrow \mathbb R$ be increasing and bounded functions. Then,
\begin{equation*}
    \langle f; g\rangle_G^\#:=\langle fg\rangle_G^\#-\langle f\rangle^\#_G\langle g\rangle^\#_G\geq 0.
\end{equation*}

\label{prop: lebowitz} 
Fix a finite weighted graph $G = (V,E,J)$. Consider two external magnetic fields $\mathsf{h}$ and $\mathsf{h}'$ satisfying $|\mathsf{h}'_x|\le \mathsf{h}_x$ for every $x\in V$. For every $A, B\subset V$, one has
\begin{equation*}
\langle \sigma_A \sigma_B \rangle - \langle \sigma_A \sigma_B \rangle' \ge |\langle \sigma_A \rangle \langle\sigma_B \rangle' - \langle \sigma_A \rangle' \langle \sigma_B \rangle|,
\end{equation*}
where $\langle \cdot \rangle$ and $\langle \cdot \rangle'$ stand for the expectations under the measures $\nu_{G,\mathsf{h}}$ and $\nu_{G,\mathsf{h}'}$ respectively.

\label{cor: ES correlations}
Let $G=(V,E,J)$ be a finite weighted graph. For every $x,y\in V$, 
\begin{align}\label{eq: es cor: 3}
\langle \sigma_x \sigma_y \rangle_{G}
&=
\phi_{G}[x\longleftrightarrow y]. 
\end{align}
More generally, given any $A \subset V$ of even cardinality,
\begin{equation} \label{eq: edwards-sokal-genA}
    \langle \sigma_A \rangle_G = \phi_G[\mathcal F_A],
\end{equation}
where $\mathcal F_A$ is the event that every connected component of $\omega$ intersects $A$ an even number of times.

\label{prop: supercritical sharpness FK-Ising}
Let $d\geq 2$ and $\beta>\beta_c$. Then, 
\begin{equation*}
\lim_{n\to \infty} \inf_{\xi}\phi^{\xi}_{\Lambda_{10n}[\beta]}[U(n)]=1,
\end{equation*}
where the infimum is taken over all partitions of $\partial\Lambda_{10n}$.

\label{rem: connectivity fk} Using classical renormalisation arguments (as described below Theorem \ref{thm:unique_currents}), one can use the above local uniqueness result to prove the following estimate, which we will use in the paper: for every $d\geq 2$ and $\beta>\beta_c$, there exists $c>0$ such that for every $N\geq n\geq0$, and every $x,y\in \Lambda_N$, one has
\begin{equation*}
    \phi_{\Lambda_N[\beta]}[\Lambda_{n}(x)\leftrightarrow \Lambda_{n}(y)]\geq 1-e^{-cn^{d-1}}.
\end{equation*}

\label{lem:switching} Let $G=(V,E,J)$ be a finite weighted graph. For every $A,B\subset V$ even, one has
   \begin{equation*}
      Z^A_G Z^B_G = \sum_{\substack{\partial \mathbf{n}=A\Delta B \\ \partial\mathbf{m}=\emptyset}} w_G(\mathbf{n})w_G(\mathbf{m}) \mathbbm{1}\{\widehat{\mathbf{n}+\mathbf{m}}\in \mathcal{F}_A\},
   \end{equation*}
   where $\mathcal{F}_A$ denotes the event that $|C\cap A|$ is even for every cluster $C$ of $\widehat{\mathbf{n}+\mathbf{m}}$, and $A\Delta B$ denotes the symmetric difference of the sets $A$ and $B$.

\label{coro:expression truncated switching} Let $d\geq 2$ and $\beta\geq 0$. For every $\Lambda\subset \mathbb Z^d$ finite and every finite $A,B\subset \Lambda$,
\begin{equation*}
    \langle \sigma_A;\sigma_B\rangle_{\Lambda[\beta]}^+=\langle \sigma_A\sigma_B\rangle_{\Lambda[\beta]}^+\mathbf{P}^{A\Delta B,\emptyset}_{\Lambda^\mathfrak{g}[\beta],\Lambda^\mathfrak{g}[\beta]}[\mathcal{F}_A^c].
\end{equation*}

\label{prop:uniqueness with sprinkling}
Let $d\geq 2$ and let $(\ell_L)_{L\geq 1}$ be a sequence such that $\ell_L=o(\log L)$ as $L\to\infty$. Then, for every $\varepsilon>0$, one has
\begin{equation*}
\lim_{L\to \infty} \inf_{\omega \in \mathcal{A}_L(\ell_L)}\mathbb{P}_{\varepsilon}[\omega\cup \gamma \in U(L)]=1.    
\end{equation*}

Let $\beta>\beta'>\beta_c$. Let $c>0$ be the constant of Proposition~\ref{prop:uniform connectivity} and for $L>0$, let $C_0=(2d/c)^{\frac{1}{d-1}}$  and \begin{equation*}
\ell=\ell_L:=C_0 (\log L)^{\frac{1}{d-1}}.
\end{equation*}
Take $L$ large enough so that $\ell_L\leq L$. By Proposition~\ref{prop:uniform connectivity} and a union bound,    
\begin{equation*}
\inf_{A,B \subset \partial \Lambda_{10L}}\mathbf{P}^{A, B}_{\widetilde{\Lambda_{10L}}[\beta,\beta'],\widetilde{\Lambda_{10L}}[\beta,\beta']}[\mathcal{A}_L]\geq 1-L^{-d}.    
\end{equation*}
Hence, by Proposition~\ref{prop:coupling},
\begin{equation*}
\inf_{A,B \subset \partial \Lambda_{10L}}\mathbf{P}^{A, B}_{\Lambda_{10L}[\beta],\Lambda_{10L}[\beta]}[U(L)]\geq (1-L^{-d})\inf_{\omega\in \mathcal{A}_L}\mathbb{P}_{\varepsilon}[\omega\cup \gamma \in U(L)],   
\end{equation*}
which tends to $1$ as $L$ tends to infinity by Proposition~\ref{prop:uniqueness with sprinkling}. This concludes the proof.

\label{prop:connectivity_old}
 	Let $\beta>\beta'>\beta_c$. There exists $c>0$ such that, for every $N \geq 2n$, every $x, y \in \Lambda_{N}$ and every $S\subset \Lambda_{N}$ of even cardinality with $S\cap (\Lambda_n(x) \cup \Lambda_n(y))=\emptyset$, we have
 	$$\mathbf{P}^{S, \emptyset}_{\widetilde{\Lambda_N}[\beta,\beta'], \widetilde{\Lambda_N}[\beta,\beta']}\Big[\Lambda_n(x)\xleftrightarrow[]{\widehat{\mathbf{n}_1 + \mathbf{n}_2}\:} \Lambda_n(y)\Big] \geq 1 - e^{-cn^{d-1}}\,.$$

\label{lem:weak weak mix}
Let $\beta>\beta_c$ and $\varepsilon>0$. For every $n$ large enough and every $A\subset\partial\Lambda_n$ of even cardinality,
\begin{equation}\label{eq:wwmixing}\langle{\sigma_A}\rangle_{\Lambda_n^\bullet} \leq e^{\varepsilon n^{d-1}}\langle {\sigma_A}\rangle_{\Lambda_n[\beta]}.\end{equation}

First note that the existence of a cluster crossing $\Lambda_{8 L}\setminus \Lambda_{ L}$ is  implied by the fact that $\omega\in\mathcal{A}_L$, so we only need to focus on the uniqueness part. 

    Enlarge the probability space and write $\gamma=\gamma^1\cup\gamma^2$, with $\gamma^1$ and $\gamma^2$ independent Bernoulli percolations with of parameter $\delta$ given by $1-\varepsilon= (1-\delta)^2$. It follows readily from (the proof of) \cite[Proposition 2.2]{SeveroSlabIsing2023} that 
    \begin{equation}\label{eq:uniqueness with sprinkling}
    	\lim_{L\to\infty} \inf_{\omega\in\mathcal{A}_L(\ell_L)} \mathbb{P}_\varepsilon \left[ \begin{array}{c}
    		\text{all clusters of } \omega \text{ crossing } \Lambda_{4L}\setminus\Lambda_{2L} \\ \text{ are connected to each other in } \omega\cup\gamma^1
    	\end{array} \right] = 1.
    \end{equation}

    We now prove that, conditionally on the event in \eqref{eq:uniqueness with sprinkling}, we have $\omega\cup\gamma\in U(L)$ with high probability, thus concluding the proof. Condition on a realization of $\gamma^1$ satisfying the event in \eqref{eq:uniqueness with sprinkling}, and denote by $C_*$ the cluster of $\omega\cup\gamma^1$ containing all the clusters of $\omega$ crossing $\Lambda_{4L}\setminus\Lambda_{2L}$. Fix a vertex $x\in \Lambda_{2L}$ and explore the cluster of $x$ in $\omega\cup\gamma = \omega\cup\gamma^1\cup\gamma^2$ in the standard way: by revealing, at each step, the state of $\gamma^2$ on an edge at the boundary of the current cluster, and adding that edge to the cluster if and only if it is open in $\omega\cup\gamma$. Notice that if the cluster of $x$ crosses the annulus $\Lambda_{4L}\setminus\Lambda_{2L}$, then the exploration reaches each annulus of the form $\Lambda_{2L + i2\ell_L}\setminus\Lambda_{2L + (i-1)2\ell_L}$, for $i\in\{1,2,\ldots, \lfloor L/\ell_L \rfloor$\}. Since $\omega\in\mathcal{A}_L(\ell_L)$, each time the exploration reaches such an annulus for the first time, it is at distance at most $2\ell_L$ from $C_*$, and therefore gets connected to $C_*$ within this annulus with probability at least $\delta^{2\ell_L}$. As a result, since $\ell_L=o(\log L)$, the probability that the cluster of $x$ crosses $\Lambda_{4L}\setminus\Lambda_{2L}$ without being connected to $C_*$ is at most $(1-\delta^{2\ell_L})^{\lfloor L/\ell_L \rfloor} \leq e^{-cL^{1-o(1)}}$. By a union bound in $x$, this yields that $\omega\cup\gamma\in U(L)$ with high probability, thus concluding the proof.

Let $\beta>\beta_c$ and denote by $\textup{Cov}(\cdot,\cdot)$ the covariance under $\nu^+_\beta=\langle \cdot\rangle^+_\beta$.
It suffices to prove the desired result for events depending on finitely many vertices.
Let $A$ be an event measurable with respect to $\Lambda_n$ and $B$ an event measurable with respect to a finite subset $S$ of $\mathbb{Z}^d\setminus \Lambda_{2n}$. Observe that the functions 
\begin{equation}\label{eq: increasing}
\pm\mathbbm{1}_A +\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x, \quad \pm\mathbbm{1}_B+\frac{1}{2}\sum_{x\in S} \sigma_x
\end{equation}
are increasing.
By the FKG inequality,
\begin{align*}
0&\leq \textup{Cov}\Big(\mathbbm{1}_A+\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x , -\mathbbm{1}_B+\frac{1}{2}\sum_{x\in S} \sigma_x\Big)+ \textup{Cov}\Big(- \mathbbm{1}_A+\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x, \mathbbm{1}_B+\frac{1}{2}\sum_{x\in S} \sigma_x\Big)\\
&=2\textup{Cov}\Big(\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x,\frac{1}{2}\sum_{x\in S} \sigma_x\Big)-2\textup{Cov}(\mathbbm{1}_A,\mathbbm{1}_B),
\end{align*}
and 
\begin{align*}
0&\leq \textup{Cov}\Big(\mathbbm{1}_A+\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x ,\mathbbm{1}_B+ \frac{1}{2}\sum_{x\in S} \sigma_x\Big)+ \textup{Cov}\Big(- \mathbbm{1}_A+\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x, - \mathbbm{1}_B+\frac{1}{2}\sum_{x\in S} \sigma_x\Big)\\
&=2\textup{Cov}\Big(\frac{1}{2}\sum_{x\in \Lambda_n} \sigma_x,\frac{1}{2}\sum_{x\in S} \sigma_x\Big)+2\textup{Cov}(\mathbbm{1}_A,\mathbbm{1}_B).
\end{align*}
Combining the above displayed equations, we obtain 
\begin{equation*}
|\textup{Cov}(\mathbbm{1}_A,\mathbbm{1}_B)|\leq \frac{1}{4}\textup{Cov}\Big(\sum_{x\in \Lambda_n} \sigma_x,\sum_{x\in S} \sigma_x\Big),    
\end{equation*}
from which it is possible to conclude thanks to Corollary \ref{coro: truncated}.

We first prove the result for random currents and for the random cluster measure. Fix $N>2n$. Let $\mathbf{m}_{in}\in \mathbb N^{E(\Lambda_n)}$ and $\mathbf{m}_{out}\in \mathbb N^{E(\Lambda_N)\setminus E(\Lambda_{2n})}$ be arbitrary current configurations with sources $A:=\partial \mathbf{m}_{in}\subset \partial\Lambda_n$ and $B:=\partial \mathbf{m}_{out}\subset \partial\Lambda_{2n}$. Below, we write $\mathbf P=\mathbf{P}^\emptyset_{\Lambda_N[\beta]}$ and abuse slightly notation by writing $Z^A_E=Z^A_G$ for a weighted graph $G=(V,E,J)$. Note that
\begin{align}
    \label{eq:mix_current_1}
    &\frac {\mathbf{P}[\mathbf{n}_{|E(\Lambda_n)}=\mathbf{m}_{in} ,\, \mathbf{n}_{|E(\Lambda_N)\setminus E(\Lambda_{2n})}=\mathbf{m}_{out}]}{\mathbf{P}[\mathbf{n}_{|E(\Lambda_n)}=\mathbf{m}_{in}]\mathbf{P}[\mathbf{n}_{|E(\Lambda_N)\setminus E(\Lambda_{2n})}=\mathbf{m}_{out}]} 
    = \frac{Z^{A\cup B}_{E(\Lambda_{2n})\setminus E(\Lambda_n)} Z^\emptyset_{\Lambda_N[\beta]}}{Z^{A}_{E(\Lambda_N)\setminus E(\Lambda_n)} Z^{B}_{\Lambda_{2n}[\beta]}} \\
    \label{eq:mix_current_2}
    &~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~= \frac{ \sum_{\tilde \mathbf{m}_{in},\, \tilde\mathbf{m}_{out}} \, w(\tilde\mathbf{m}_{in})w(\tilde\mathbf{m}_{out}) Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{A\cup B} Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{\tilde A\cup \tilde B} }{ \sum_{\tilde \mathbf{m}_{in},\, \tilde\mathbf{m}_{out}} \, w(\tilde\mathbf{m}_{in})w(\tilde\mathbf{m}_{out}) Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{A\cup \tilde B} Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{\tilde A\cup B} },
\end{align}
where in the last line we decomposed $Z^\emptyset_{\Lambda_N[\beta]}$,  $Z^{A}_{E(\Lambda_N)\setminus E(\Lambda_n)}$ and $Z^{B}_{\Lambda_{2n}[\beta]}$ according to the restrictions $\tilde \mathbf{m}_{in}$ and $\tilde\mathbf{m}_{out}$ of the currents to
$E(\Lambda_n)$ and $E(\Lambda_N)\setminus E(\Lambda_{2n})$, with sources $\tilde A:=\partial \tilde\mathbf{m}_{in}\subset \partial\Lambda_n$ and $\tilde B:=\partial \tilde \mathbf{m}_{out}\subset \partial\Lambda_{2n}$. By the switching lemma and the proof of Corollary~\ref{coro: truncated} (see also Remark~\ref{rem: free even mixing}), we have
\begin{equation*}
    0\leq \frac{Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{A\cup B}Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{\emptyset}}{Z_{E(\Lambda_{2n}) \setminus E(\Lambda_n)}^{A} Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{ B}} -1 
    = \frac{ \langle\sigma_A;\sigma_B\rangle_{ E(\Lambda_{2n})\setminus E(\Lambda_n)} }{\langle\sigma_A\rangle_{E(\Lambda_{2n})\setminus E(\Lambda_n)} \langle\sigma_B\rangle_{E(\Lambda_{2n})\setminus E(\Lambda_n)} } \leq e^{-cn},
\end{equation*}
uniformly on the even sets $A\subset \partial\Lambda_n$ and $B\subset\partial\Lambda_{2n}$. In particular, we have
\begin{equation*}
    \left| \frac{Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{A\cup B} Z_{E(\Lambda_{2n}) \setminus E(\Lambda_n)}^{\tilde A\cup \tilde B}}{Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{A\cup \tilde B} Z_{E(\Lambda_{2n})\setminus E(\Lambda_n)}^{\tilde A\cup B}} - 1 \right| \leq e^{-cn}.
\end{equation*}
Plugging this bound into \eqref{eq:mix_current_2}, we conclude that 
\begin{equation*}
    \left| \frac{\mathbf{P}[\mathbf{n}_{|E(\Lambda_n)}=\mathbf{m}_{in} ,\, \mathbf{n}_{|E(\Lambda_N)\setminus E(\Lambda_{2n})}=\mathbf{m}_{out}]}{\mathbf{P}[\mathbf{n}_{|E(\Lambda_n)}=\mathbf{m}_{in}]\mathbf{P}[\mathbf{n}_{|E(\Lambda_N)\setminus E(\Lambda_{2n})}=\mathbf{m}_{out}]}  - 1 \right| \leq e^{-cn}.
\end{equation*}
Exponential ratio mixing follows for $\mathbf{P}=\mathbf{P}^\emptyset_{\Lambda_N[\beta]}$ by summing over $\mathbf{m}_{in}\in E$ and $\mathbf{m}_{out}\in F$, and then for $\mathbf{P}_\beta$ by taking $N\to\infty$.

Since $\phi_\beta$ is a Bernoulli sprinkling of $\mathbf{P}_\beta$ (see e.g.~\cite{LupuWerner2016note,AizenmanDuminilTassionWarzelEmergentPlanarity2019}), exponential ratio mixing for the former follows readily from the exponential ratio mixing of the latter.
